import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第90章 门口","description":"","frontmatter":{},"headers":[],"relativePath":"第90章_门口.md","filePath":"第90章_门口.md"}'),o={name:"第90章_门口.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第90章-门口" tabindex="-1">第90章 门口 <a class="header-anchor" href="#第90章-门口" aria-label="Permalink to &quot;第90章 门口&quot;">​</a></h1><p>大四那年选方向，我又站了一次门口。</p><p>这一次我知道我在干什么。</p><p>三月，我们那届要填一个东西：考研、保研、还是工作。</p><p>我的成绩在保研的边缘。</p><p>边缘的意思是，往前一名我就有，往后一名我就没有。</p><p>我那天去问了周老师。</p><p>周老师这个人钝，他什么都看不出来，他只教书。</p><p>他翻我的成绩，翻了两遍。</p><p>他说，你可以争一下。</p><p>我说，争哪个。</p><p>他说，你去看简章。</p><p>他说，我只说一句，你这个数学还行，英语不行，你别选一个考英语的。</p><p>我说，好。</p><p>他说，你这个孩子，你怎么每次答应得这么快。</p><p>我说，我记住了。</p><p>他说，你没记住。</p><p>他说，你现在心里已经有地方了。</p><p>我坐在那儿。</p><p>我说，没有。</p><p>周老师说，你来我这儿三年了。</p><p>他说，你进门从来不敲。</p><p>他说，你今天进门敲了两下。</p><p>他说，敲两下的人是有事求自己。</p><p>他说，你有事求自己，说明你已经定了。</p><p>我说，我定了个地方。</p><p>他说，哪儿。</p><p>我说，我还没讲。</p><p>他说，那你说。</p><p>我说，宁城。</p><p>周老师把那本成绩合上。</p><p>他说，宁城。</p><p>我说，嗯。</p><p>他说，宁城那个学校你考不上。</p><p>我说，他们的方向我看过。</p><p>他说，我不是说方向。</p><p>他说，我说的是你数学行英语不行，他们那一个要考英语一，你过不了线。</p><p>他说，我给你换一个。</p><p>我说，不用。</p><p>他说，你为什么非要这一个。</p><p>我说，这个方向好。</p><p>他说，你把方向讲出来我听听。</p><p>我说，就是做那个东西。</p><p>他说，哪个东西。</p><p>我说，我们那个实验室有一个老师在做那个。</p><p>他说，宁城那个学校没有他。</p><p>他说，你这个方向我看得懂，你别糊弄我。</p><p>我坐在那儿不说话。</p><p>周老师把本子推给我。</p><p>他说，我不管你去哪儿。</p><p>他说，我只说一句。</p><p>他说，你这个分，你去一个你考得上的地方，你今年就有书读。</p><p>他说，你去宁城，你今年没有。</p><p>他说，你明年再考，你明年这个状态不一定还在。</p><p>他说，你自己想。</p><p>他说，你想好了你来找我，我给你签字。</p><p>那天我从他办公室出来，在走廊上站着。</p><p>我知道我在干什么。</p><p>宁城是她那边回来第一个落脚的城市。</p><p>她说过，她那种展如果要办第二场，只可能在两个城市办。</p><p>一个是澄江。</p><p>一个是宁城。</p><p>而澄江是我现在这个城市。</p><p>宁城是那个我从来没有任何关系、没有任何朋友、没有任何老师的城市。</p><p>我要去那儿，理由只有一个：她回来的那天，飞机落的地方离我近三百公里。</p><p>那年四月陈树跟我提过一次。</p><p>不是他主动。</p><p>是我们在食堂，我在看那个学校的简章。</p><p>他探头看了一眼。</p><p>他说，宁城？</p><p>我说，嗯。</p><p>他说，你去那儿干什么。</p><p>我说，方向。</p><p>他说，什么方向。</p><p>我说，做东西。</p><p>他说，你做的那个东西澄江就有。</p><p>我说，澄江那个老师不带人。</p><p>他说，你查过宁城那个老师带几个人吗。</p><p>我说，查过。</p><p>他说，带几个。</p><p>我说，两个。</p><p>他说，那你凭什么进得去。</p><p>我那天没答。</p><p>陈树把筷子放下。</p><p>他说了一句我听了两年的话。</p><p>他说，你怎么又在门口站着。</p><p>我说，什么门口。</p><p>他说，你去年跟我讲过你填志愿那次，你懂我说什么。</p><p>他说，你现在这个叫门口。</p><p>他说，门口不算房子，你站四年你也是站在门口。</p><p>我说，我知道。</p><p>他说，你知道你还去。</p><p>我说，因为我这次是自己算出来的。</p><p>他说，算出来什么。</p><p>我说，算出来我考不上。</p><p>我说，周老师讲我考不上，你也讲我进不去，我自己算了一遍，我考不上的概率是七成。</p><p>他说，那你干嘛去。</p><p>我说，因为剩下那三成，是她回来那天我离她三百公里。</p><p>我说，我知道这个理由很难看。</p><p>我说，我这辈子所有的难看理由，全部写在同一个本子里。</p><p>他说，那你为什么现在还讲给我听。</p><p>我说，因为我今年不想再瞒一个人。</p><p>我说，我瞒了她四年。</p><p>我说，我瞒了我妈，我瞒了沈聿，我瞒了你。</p><p>我说，我今天不讲给一个人听，我今天晚上自己会改。</p><p>陈树坐在那儿，把那个餐盘往前推了一下。</p><p>他说，行。</p><p>他说，你说完了？</p><p>我说，说完了。</p><p>他说，那我讲两句。</p><p>他说，第一句，我不劝你，我去年劝过沈聿那种话，我知道劝不动。</p><p>他说，第二句，你要是今年没考上，你别去找她。</p><p>他说，你别拿你那年在门口站空了这件事，去跟她算。</p><p>他说，你一发这个，你就把她变成你这三年的账。</p><p>我说，我不算。</p><p>他说，你会。</p><p>他说，你今晚就会在本子上写&quot;我为了这个多熬了六个月&quot;。</p><p>我说，我不会写。</p><p>他说，你会写。</p><p>他说，你写完了你会划掉。</p><p>他说，你划掉那个动作，比写上去还快。</p><p>那天下午我回宿舍，坐在床上。</p><p>我把那个简章从书包里拿出来。</p><p>我拿笔画了一个圈。</p><p>圈的是宁城。</p><p>我在旁边写了一行。</p><p>我写：七成考不上。</p><p>我写：我还是要报这一个。</p><p>我把简章合上。</p><p>我那天夜里跟她讲了。</p><p>我没讲宁城，我没讲概率。</p><p>我讲的是：我今年可能不考上。</p><p>她说，那你怎么打算。</p><p>我说，我再考一年。</p><p>她隔了很久。</p><p>然后她说了一句。</p><p>她说，你不要报宁城。</p><p>我拿着手机，坐在黑暗里。</p><p>我说，你怎么知道。</p><p>她说，我不知道。</p><p>她说，我今天下午忽然想到一件事。</p><p>她说，你要是为了我选一个地方，你会选离我落地的地方近的。</p><p>她说，我落地只有两个地方。</p><p>她说，一个是这儿，一个是宁城。</p><p>她说，你在这儿读了四年。</p><p>她说，那你只剩一个。</p><p>我说，你就让我猜一次你为什么讲这句。</p><p>她说，我讲这句是因为我今年要签那个活了。</p><p>她说，我签了，我明年这个时候可能不回来。</p><p>她说，我要是不回来，你今年考到宁城，你明年在宁城站一年。</p><p>她说，我不想你站一年。</p><p>我说，那你希望我报哪儿。</p><p>她说，报一个你考得上的。</p><p>她说，报一个有朋友的。</p><p>她说，报一个你明天能走去吃那家面馆的。</p><p>我说，你讲的这三条，没有一条是我会听的。</p><p>她说，我知道。</p><p>她说，我今天讲了，我就不欠你了。</p><p>她说，你要是明年站在宁城没考上，你别在心里讲&quot;我早就跟你说过&quot;。</p><p>她说，我今天说过一次。</p><p>她说，你要是不听，那是你的事。</p><p>我说，那我今年就考宁城。</p><p>她说，好。</p><p>她说，那我以后不跟你讲这个了。</p><p>我说，你别讲。</p><p>她说，我不讲。</p><p>她说，我只讲一次。</p><p>那天我下线很早。</p><p>我在本子上写了那一行，写完了我划掉了。</p><p>划掉那一下很快。</p><p>陈树说得一点没错。</p><p>我写&quot;我为了这个多熬了六个月&quot;，我用不到十秒钟。</p><p>我划掉它，我用不到三秒。</p>',173)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
